import * as T from './vendor/three.module.js';
import {sampleWeightedWindow as sampleWeightedRoll,WINDOW_DURATION as ROLL_DURATION,WINDOW_PHASES as ROLL_PHASES,WINDOW_IMPACT} from './weighted-window.js';
import {createWindowShatter} from './window-shatter.js';
const $=id=>document.getElementById(id),renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x273633);$('scene').append(renderer.domElement);
const scene=new T.Scene(),camera=new T.OrthographicCamera(),sun=new T.DirectionalLight(0xfff2d5,2.3);sun.position.set(-3,5,5);scene.add(sun,new T.HemisphereLight(0xe2f4ed,0x37413c,2));
const floor=new T.Mesh(new T.PlaneGeometry(30,30),new T.MeshStandardMaterial({color:0x4c5c52,roughness:1}));floor.rotation.x=-Math.PI/2;floor.position.y=-.003;scene.add(floor);const grid=new T.GridHelper(20,40,0x89988b,0x617369);scene.add(grid);
const capsuleMaterial=new T.MeshStandardMaterial({color:0x8ac7d4,transparent:true,opacity:.17,depthWrite:false}),boneMaterial=new T.MeshStandardMaterial({color:0xd6e9ed}),weightMaterial=new T.MeshStandardMaterial({color:0x38aee0}),jointMaterial=new T.MeshStandardMaterial({color:0xe6dfbd});
const start=sampleWeightedRoll(0),bodies=start.segments.map(s=>{const group=new T.Group(),envelope=new T.Mesh(new T.CapsuleGeometry(s.radius,s.length,4,8),capsuleMaterial),bone=new T.Mesh(new T.CylinderGeometry(.012,.012,s.length,6),boneMaterial),weight=new T.Mesh(new T.SphereGeometry(.032*Math.cbrt(s.mass),12,8),weightMaterial);if(s.name==='head'){weight.material=new T.MeshStandardMaterial({color:0xf18a65});envelope.material=capsuleMaterial.clone();envelope.material.color.set(0xf1a485);const face=new T.Mesh(new T.ConeGeometry(.026,.07,5),new T.MeshBasicMaterial({color:0xffd0b6}));face.rotation.z=-Math.PI/2;face.position.x=.10;group.add(face);}group.add(envelope,bone,weight);scene.add(group);return {group,envelope};});
const joints=Object.fromEntries(Object.keys(start.points).map(id=>{const m=new T.Mesh(new T.SphereGeometry(.018,8,6),jointMaterial);scene.add(m);return [id,m];}));
const center=new T.Mesh(new T.SphereGeometry(.035,16,10),new T.MeshBasicMaterial({color:0xffce50,depthTest:false}));center.renderOrder=5;scene.add(center);
const projection=new T.Mesh(new T.RingGeometry(.035,.052,20),new T.MeshBasicMaterial({color:0xffce50,side:T.DoubleSide}));projection.rotation.x=-Math.PI/2;scene.add(projection);
const contactMaterial=new T.MeshBasicMaterial({color:0x86ed8c,side:T.DoubleSide}),contacts=Array.from({length:50},()=>{const m=new T.Mesh(new T.RingGeometry(.022,.04,16),contactMaterial);m.rotation.x=-Math.PI/2;scene.add(m);return m;});
const lineGeometry=new T.BufferGeometry().setFromPoints([new T.Vector3(),new T.Vector3()]),line=new T.Line(lineGeometry,new T.LineDashedMaterial({color:0xffce50,dashSize:.035,gapSize:.025}));scene.add(line);
const track=new T.Line(new T.BufferGeometry().setFromPoints(Array.from({length:161},(_,i)=>new T.Vector3(...sampleWeightedRoll(ROLL_DURATION*i/160).center))),new T.LineBasicMaterial({color:0xe3b755,transparent:true,opacity:.55}));scene.add(track);
const wall=new T.Group(),wallMat=new T.MeshStandardMaterial({color:0x9b9683,roughness:1,transparent:true,opacity:.8}),frameMat=new T.MeshStandardMaterial({color:0xead9a5,roughness:.9});scene.add(wall);
function box(y,z,h,w,material=wallMat,depth=.16){const m=new T.Mesh(new T.BoxGeometry(depth,h,w),material);m.position.set(0,y,z);wall.add(m);}
box(.425,0,.85,1);box(1.775,0,.45,1);for(const z of [-.8,.8])box(1,z,2,.6);
for(const y of [.8625,1.5375])box(y,0,.025,1,frameMat,.18);for(const z of [-.4875,.4875])box(1.2,z,.7,.025,frameMat,.18);
const glass=createWindowShatter({kind:'window-concrete'});glass.group.rotation.y=Math.PI/2;scene.add(glass.group);
const audio=new Audio('../assets/audio/glass-smash-rubberduck-cc0.ogg');audio.volume=.65;audio.preload='auto';
function stopAudio(){audio.pause();audio.currentTime=0;}
$('sound').onchange=()=>{if(!$('sound').checked)stopAudio();};
$('time').max=ROLL_DURATION;
let time=0,playing=false,last=performance.now(),state=start;
function render(){state=sampleWeightedRoll(time);glass.sample(state.glassTime);wall.visible=!$('cutaway').checked;state.segments.forEach((s,i)=>{const a=new T.Vector3(...state.points[s.a]),b=new T.Vector3(...state.points[s.b]),body=bodies[i];body.group.position.copy(a).lerp(b,.5);body.group.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),b.sub(a).normalize());body.envelope.visible=$('envelope').checked;});for(const [id,p]of Object.entries(state.points))joints[id].position.fromArray(p);center.position.fromArray(state.center);projection.position.set(state.center[0],.004,state.center[2]);projection.material.color.set(state.mode==='static kneel'?(state.balanced?0x86ed8c:0xff6644):0xffce50);
 contacts.forEach((m,i)=>{m.visible=i<state.contacts.length;if(m.visible)m.position.set(state.contacts[i].point[0],.006,state.contacts[i].point[2]);});lineGeometry.attributes.position.setXYZ(0,...state.center);lineGeometry.attributes.position.setXYZ(1,state.center[0],.008,state.center[2]);lineGeometry.attributes.position.needsUpdate=true;line.computeLineDistances();track.visible=$('path').checked;
 $('time').value=time;$('play').textContent=playing?'Pause':'Play';$('status').textContent=`${time.toFixed(2)} / ${ROLL_DURATION.toFixed(2)} s  |  ${state.phase}  |  ${state.totalMass} kg  |  ${state.mode==='static kneel'?(state.balanced?'Kneel supported':'Outside support'):'Moving  -  balance is dynamic'}`;$('contacts').textContent='Floor contact: '+[...new Set(state.contacts.map(c=>c.segment))].join(', ');renderer.render(scene,camera);}
function resize(){const w=$('scene').clientWidth,h=$('scene').clientHeight;renderer.setSize(w,h,false);const span=4.8;camera.left=-span*w/h/2;camera.right=span*w/h/2;camera.top=span/2;camera.bottom=-span/2;camera.near=.01;camera.far=100;camera.position.set(...({side:[1.3,1.6,9],three:[-4,3.3,8],front:[9,2.3,0]}[$('view').value]));camera.lookAt(1.3,.8,0);camera.updateProjectionMatrix();render();}
function seek(t){if(!Number.isFinite(t))throw Error('Invalid seek');playing=false;stopAudio();time=T.MathUtils.clamp(t,0,ROLL_DURATION);render();return state;}
$('play').onclick=()=>{if(time>=ROLL_DURATION)time=0;playing=!playing;if(!playing)stopAudio();last=performance.now();render();};$('reset').onclick=()=>seek(0);$('time').oninput=()=>seek(Number($('time').value));$('view').onchange=resize;for(const id of ['envelope','path','cutaway'])$(id).onchange=render;for(const phase of ROLL_PHASES){const b=document.createElement('button');b.textContent=phase.label;b.onclick=()=>seek((phase.start+phase.end)/2);$('phases').append(b);}window.addEventListener('resize',resize);document.addEventListener('visibilitychange',()=>{if(document.hidden){playing=false;stopAudio();render();}});
const params=new URLSearchParams(location.search);if(['side','three','front'].includes(params.get('view'))) $('view').value=params.get('view');
window.weightedWindowStudy={seek,diagnostics:()=>({...state,glass:glass.diagnostics()})};function tick(now){if(playing){const previous=time;time=Math.min(ROLL_DURATION,time+Math.min((now-last)/1000,.05)*Number($('speed').value));if(previous<WINDOW_IMPACT&&time>=WINDOW_IMPACT&&$('sound').checked){audio.playbackRate=Number($('speed').value);audio.play().catch(()=>{});}if(time>=ROLL_DURATION)playing=false;render();}last=now;requestAnimationFrame(tick);}resize();requestAnimationFrame(tick);
